package com.fpe.registry;

import java.util.LinkedHashMap;
import java.util.Map;

import com.fpe.FpeMod;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvent;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

/** Custom voice lines (assets/fpe/sounds/*, declared in sounds.json; generated by tools/gen_voice.py). */
public final class ModSounds {
    private ModSounds() {}

    public static final DeferredRegister<SoundEvent> SOUNDS = DeferredRegister.create(ForgeRegistries.SOUND_EVENTS, FpeMod.MODID);
    private static final Map<String, RegistryObject<SoundEvent>> MISS_CIRCLE = new LinkedHashMap<>();

    static {
        for (String id : new String[] { "you_failed", "wrong", "detention", "zero", "sit_down", "pop_quiz", "do_math", "try_again", "class_dismissed",
                "late", "fail3", "perfect", "come_here", "confiscated", "hurt", "death" }) {
            String name = "miss_circle." + id;
            MISS_CIRCLE.put(id, SOUNDS.register(name, () -> SoundEvent.createVariableRangeEvent(new ResourceLocation(FpeMod.MODID, name))));
        }
    }

    public static SoundEvent missCircle(String id) { return MISS_CIRCLE.get(id).get(); }
}
